        question: 'என் திடீர் வெப்ப அலைகளைப் பதிவு செய்ய முடியுமா?',
        subtitle: 'காலப்போக்கில் அவற்றின் அதிர்வெண்ணைக் கவனியுங்கள்.',
        answer: 'ஆம். திடீர் வெப்ப அலைகள், மாதவிடாய் நிறுத்தத்துக்கு முந்தைய / மாதவிடாய் நிறுத்தப் பயன்முறையில் கிடைக்கும் அறிகுறிகளில் ஒன்று.',
