        subtitle: 'சில ஆய்வக முடிவுகளை உங்கள் கண்காணிப்பில் சேருங்கள்.',
        answer: 'ஆம். FSH மற்றும் எஸ்ட்ராடியோல் போன்ற ஆய்வக முடிவுகளை இந்தப் பயன்முறையில் பதிவு செய்யலாம்.',
