        answer: 'உங்கள் கண்காணிப்பில் கிடைக்கும் தகவலிலிருந்து கர்ப்பக் கண்காணிப்பு உங்கள் மதிப்பிடப்பட்ட பிரசவ தேதியைக் கணக்கிடுகிறது.',
