        subtitle: 'உங்கள் கர்ப்பத்தின் முன்னேற்றத்தை வாரந்தோறும் பாருங்கள்.',
        answer: 'ஆம். AWA வாரந்தோறும் கண்காணிப்பை வழங்குகிறது, உங்கள் கர்ப்பம் எப்படி முன்னேறுகிறது என்பதைக் காட்டுகிறது.',
