        answer: 'கர்ப்பக் கண்காணிப்பில் நீங்கள் உணரும் அறிகுறிகள், எடை, மனநிலை, உறக்கம் மற்றும் தனிப்பட்ட மருத்துவத் தகவல் ஆகியவை அடங்கலாம்.',
