        subtitle: 'உங்கள் சுழற்சி படிப்படியாகத் தொடங்குவதைப் பாருங்கள்.',
        answer: 'உங்கள் சுழற்சி திரும்புதல், மாதவிடாய் மீண்டும் தொடங்குதல் மற்றும் பிரசவத்துக்குப் பின் உங்கள் ஹார்மோன் மாற்றங்களை AWA கண்காணிக்கிறது.',
