        subtitle: 'உங்கள் வேகத்தில் உங்கள் கண்காணிப்பை மீண்டும் தொடங்குங்கள்.',
        answer: 'கருச்சிதைவுக்குப் பின் உங்கள் சுழற்சி திரும்புவதை AWA கண்காணிக்கிறது, வழக்கமான மாதவிடாய்க் கண்காணிப்பை உடனே திணிக்காமல் உங்கள் வரலாற்றைப் படிப்படியாகத் தொடர உதவுகிறது.',
