        subtitle: 'நீங்கள் குறிக்க விரும்பும் உடல் அறிகுறிகளைக் கண்காணியுங்கள்.',
        answer: 'உடல் அறிகுறிகளைக் கண்காணிப்பது இந்தப் பயணத்தில் கிடைக்கிறது.',
