        answer: 'ஆன்மிகக் குறிப்புகள் இயக்கப்பட்டிருக்கும்போது, உங்கள் மாதவிடாயையும் உங்கள் தூய்மைக் காலத்தையும் வேறுபடுத்தும் ஓர் இரகசியக் குறிகாட்டியை AWA காட்டலாம்.',
